// on new post: write the post id into every follower's feed
async function pushToFeeds(post) {
  const followers = await graph.followersOf(post.authorId); // all of them
  for (const f of followers) {
    const feed = await feedCache.get(f) ?? [];
    feed.unshift({ post });          // store the full post object at the front
    await feedCache.set(f, feed);    // no cap on length
  }
}
